val arFragment = supportFragmentManager.findFragmentById(R.id.ar_fragment) as ArFragment
arFragment.setOnTapArPlaneListener { hit, _, _ ->
    val anchor = hit.createAnchor()
    val anchorNode = AnchorNode(anchor).apply { setParent(arFragment.arSceneView.scene) }
    ModelRenderable.builder().setSource(this, Uri.parse("model.glb")).build()
        .thenAccept { TransformableNode(arFragment.transformationSystem).apply { renderable = it; setParent(anchorNode) } }
}
